article.sections.8.blocks.5.text:
@dataclass(frozen=True)
class LoopDecision:
    keyword: str
    revision_count: int
    stop_reason: Literal["excellent", "revision_limit"] | None

article.sections.8.blocks.6.text:
def decide_next_step(
    keyword: str,
    revision_count: int,
    editor_says_excellent: bool,
) -> LoopDecision:
    if revision_count < 0:
        raise ValueError("revision_count must be nonnegative")

article.sections.8.blocks.7.text:
if editor_says_excellent:
        reason = "excellent"
    elif revision_count >= 1:
        reason = "revision_limit"
    else:
        reason = None
